	const row = first(get(slip, 'breakdown.statutory', []).filter((item) => item.code === code));
	return Number(get(row, 'employee', 0)) - Number(get(row, 'overpaid', 0));
};
const paid = (slip) =>
	[
		['SEVERANCE', stop(slip, 'SEVERANCE') - stop(slip, 'ADDITIONAL_WAGES')],
		['PENSION_BENEFIT', stop(slip, 'PENSION_BENEFIT') - stop(slip, 'SEVERANCE')],
		['PPH21_FINAL_SEVERANCE.employee', tax(slip, 'PPH21_FINAL_SEVERANCE')],
		['PPH21_FINAL_PENSION.employee', tax(slip, 'PPH21_FINAL_PENSION')]
	].filter((move) => move[1] !== 0);
const balanceOf = (slip) => first(ctx.reads.employee_balance.filter((row) => row.employee_id === slip.employee_id));
// An effect can run again after a crash: what this run posted is already here.
if (ctx.reads.ledger_entry.some((row) => get(row, 'source_id.id', '') === ctx.entry.id)) return [];
return ctx.reads.payslip.flatMap((slip) => {
	const balance = balanceOf(slip);
	if (balance == null) return [];
	return paid(slip).map((move) => ({
		balance_id: balance.id,
		operation: move[1] > 0 ? 'ADD' : 'DEDUCT',
		account: 'benefit_paid',
		code: month + '.' + move[0],
		amount: Math.abs(move[1]),
		unit: 'MONEY',
		effective_on: ctx.entry.pay_date,
		source_id: { model: 'payroll_run', id: ctx.entry.id }
	}));
});

