	const row = first(get(slip, 'breakdown.statutory', []).filter((item) => item.code === code));
	return Number(get(row, 'employee', 0)) - Number(get(row, 'overpaid', 0));
};
const paid = (slip) =>
	[
		['SEVERANCE', stop(slip, 'SEVERANCE') - stop(slip, 'ADDITIONAL_WAGES')],
		['PENSION_BENEFIT', stop(slip, 'PENSION_BENEFIT') - stop(slip, 'SEVERANCE')],
		['PPH21_FINAL_SEVERANCE.employee', tax(slip, 'PPH21_FINAL_SEVERANCE')],
