	].filter((move) => move[1] !== 0);
const balanceOf = (slip) => first(ctx.reads.employee_balance.filter((row) => row.employee_id === slip.employee_id));
return ctx.reads.payslip.flatMap((slip) => {
	const balance = balanceOf(slip);
