	const next = moves.reduce((total, move) => {
		const key = month + '.' + move[0];
		return { ...total, [key]: (Object.hasOwn(total, key) ? Number(total[key]) : 0) + move[1] };
	}, { ...held, ['run.' + ctx.entry.id]: 1 });
	return [{ target: balance.id, set: { account: { ...balance.account, benefit_paid: next } } }];
});

